import{_ as a,c as r,o as s,ah as i,j as e,a as n}from"./chunks/framework.oAolcYhj.js";const l="/Qonnectra-docs/pr-14/images/manual/teil-a/dashboard.jpg",d="/Qonnectra-docs/pr-14/images/manual/teil-a/dashboard_project.jpg",h="/Qonnectra-docs/pr-14/images/manual/teil-a/dashboard_project_detail.jpg",o="/Qonnectra-docs/pr-14/images/manual/teil-a/dashboard_tabs.jpg",u="/Qonnectra-docs/pr-14/videos/dashboard_tabs.webm",c="/Qonnectra-docs/pr-14/images/manual/teil-a/dashboard_overview.jpg",g="/Qonnectra-docs/pr-14/images/manual/teil-a/dashboard_warranty.jpg",m="/Qonnectra-docs/pr-14/images/manual/teil-a/dashboard_trench.jpg",b="/Qonnectra-docs/pr-14/images/manual/teil-a/dashboard_trench_hover.jpg",p="/Qonnectra-docs/pr-14/videos/dashboard_chart_hover.webm",k="/Qonnectra-docs/pr-14/images/manual/teil-a/dashboard_conduit.jpg",z="/Qonnectra-docs/pr-14/images/manual/teil-a/dashboard_node.jpg",f="/Qonnectra-docs/pr-14/images/manual/teil-a/dashboard_address.jpg",w="/Qonnectra-docs/pr-14/images/manual/teil-a/dashboard_area.jpg",P=JSON.parse('{"title":"4. Dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"manual/teil-a-anwenderhandbuch/04-dashboard.md","filePath":"manual/teil-a-anwenderhandbuch/04-dashboard.md"}'),_={name:"manual/teil-a-anwenderhandbuch/04-dashboard.md"};function A(D,t,S,R,T,K){return s(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="_4-dashboard" tabindex="-1">4. Dashboard <a class="header-anchor" href="#_4-dashboard" aria-label="Permalink to &quot;4. Dashboard&quot;">​</a></h1><p>Das <strong>Dashboard</strong> ist die zentrale Übersichtsseite von Qonnectra. Es fasst den dokumentierten Netzbestand eines Projekts in Kennzahlen und Diagrammen zusammen, damit Sie den Ausbauzustand ohne Umweg über Listen oder die Karte erfassen können. Nach der Anmeldung ist das Dashboard die Startansicht; später erreichen Sie es über die linke Navigation durch Klicken auf den Menüpunkt „Dashboard“ in der Gruppe „Info“.</p><p><img src="'+l+'" alt="Screenshot Dashboard" data-zoomable="true"></p><p>Alle Inhalte des Dashboards beziehen sich immer auf das Projekt, das oben links in der Kopfzeile ausgewählt ist. Die Auswertungen sind ausschließlich zur Ansicht bestimmt: Sie können hier keine Werte bearbeiten, und eine Exportfunktion für Kennzahlen oder Diagramme gibt es nicht.</p><p>Hinweis: Die Kennzahlen werden auf dem Server bis zu fünf Minuten zwischengespeichert. Daten, die Sie gerade in einer anderen Ansicht erfasst haben, erscheinen deshalb unter Umständen erst mit einigen Minuten Verzögerung – ein Neuladen der Seite beschleunigt das nicht.</p><h2 id="_4-1-projekt-auswahlen" tabindex="-1">4.1 Projekt auswählen <a class="header-anchor" href="#_4-1-projekt-auswahlen" aria-label="Permalink to &quot;4.1 Projekt auswählen&quot;">​</a></h2><p>Bevor Kennzahlen sichtbar werden, muss ein Projekt ausgewählt sein. Die Projektauswahl befindet sich oben links in der Kopfzeile und ist eine Kombination aus Eingabefeld und Auswahlliste. Solange kein Projekt gewählt ist, steht im Feld der Platzhalter „Projekt“. Gehen Sie so vor:</p><ol><li>Klicken Sie auf den Pfeil nach unten am rechten Rand des Feldes. Die Liste aller für Sie freigegebenen Projekte öffnet sich. Alternativ tippen Sie in das Feld; die Liste zeigt dann nur noch Projekte, deren Name Ihre Eingabe enthält.</li><li>Klicken Sie auf den gewünschten Eintrag. Das aktuell gewählte Projekt ist in der Liste farbig hinterlegt.</li></ol><p>Alle Karten und Diagramme des Dashboards werden daraufhin automatisch neu geladen.</p><p class="img-row"><img src="'+d+'" alt="Screenshot Dashboard mit Hervorhebung der Projektauswahl oben links in der Kopfzeile" data-zoomable="true"><img src="'+h+'" alt="Screenshot Ausschnittvergrößerung der geöffneten Projektliste in der Kopfzeile mit dem hervorgehobenen Eintrag „Testprojekt“" data-zoomable="true"></p><p>Wichtig: Die Eingabe im Feld allein wählt nichts aus – erst der Klick auf einen Eintrag der Liste wechselt das Projekt. Passt kein Projekt zu Ihrer Eingabe, zeigt die Liste wieder alle Projekte an; eine Meldung über den fehlenden Treffer erscheint nicht.</p><p>Ist noch kein Projekt gewählt, bleiben alle Kennzahlen auf Null und die Diagramme zeigen „Keine Daten verfügbar“.</p><p>Hinweis: Die Projektauswahl gilt für die gesamte Anwendung und bleibt beim Wechsel in eine andere Ansicht erhalten (siehe Kapitel <a href="./03-einstieg-und-anmeldung.html">Einstieg und Anmeldung</a>). Sind für Ihr Benutzerkonto keine Projekte freigegeben, erscheint anstelle des Feldes der Hinweis „Keine Projekte verfügbar“.</p><h2 id="_4-2-reiter-im-dashboard" tabindex="-1">4.2 Reiter im Dashboard <a class="header-anchor" href="#_4-2-reiter-im-dashboard" aria-label="Permalink to &quot;4.2 Reiter im Dashboard&quot;">​</a></h2><p>Unterhalb der Kopfzeile stehen sechs Reiter (Tabs) waagerecht nebeneinander:</p><ul><li>„Übersicht“ – Kennzahlen aller Datenbereiche auf einen Blick</li><li>„Trasse“ – Auswertungen zu den Trassen</li><li>„Rohre“ – Auswertungen zu den Rohren</li><li>„Netzknoten“ – Auswertungen zu den Netzknoten</li><li>„Adressen“ – Auswertungen zu Adressen und Wohneinheiten</li><li>„Gebiete“ – Auswertungen zu Gebieten und deren Abdeckung</li></ul><p><img src="'+o+'" alt="Screenshot Dashboard mit Hervorhebung der Reiterleiste oberhalb der Inhaltsfläche" data-zoomable="true"></p><p>Sie wechseln durch Klicken auf die jeweilige Beschriftung zwischen den Ansichten. Der aktive Reiter ist farbig hervorgehoben und durch einen Balken unter der Beschriftung gekennzeichnet. Der Wechsel lädt keine Daten nach: Alle Auswertungen werden beim Öffnen des Dashboards gemeinsam geladen und stehen anschließend sofort bereit.</p>',18),e("p",null,[e("video",{src:u,controls:"",playsinline:"",preload:"metadata"},[n(" Ihr Browser unterstützt das Abspielen von HTML5-Videos nicht. Sie können die Datei "),e("a",{href:"/videos/dashboard_tabs.webm",download:""},"herunterladen"),n(" anstelle des Videos. ")])],-1),i('<p>Hinweis: Bei einem schmalen Fenster sind nicht alle sechs Beschriftungen gleichzeitig zu sehen. Die Reiterleiste lässt sich dann waagerecht verschieben, zeigt dabei aber keinen Rollbalken. Auch die Inhaltsfläche unterhalb der Leiste ist scrollbar – die unteren Karten und Diagramme eines Reiters werden erst nach dem Scrollen sichtbar.</p><p>Hinweis: Der gewählte Reiter wird nicht gespeichert. Verlassen Sie das Dashboard und kehren später zurück, ist wieder „Übersicht“ aktiv.</p><p>Hinweis: Liegen für ein Diagramm keine Werte vor, steht an seiner Stelle „Keine Daten verfügbar“. Das ist kein Fehler: In einem Projekt, in dem eine Angabe durchgängig fehlt – etwa die Netzebene der Rohre –, bleibt das zugehörige Diagramm leer, während die übrigen gefüllt sind.</p><h3 id="_4-2-1-ubersicht" tabindex="-1">4.2.1 Übersicht <a class="header-anchor" href="#_4-2-1-ubersicht" aria-label="Permalink to &quot;4.2.1 Übersicht&quot;">​</a></h3><p>Der Reiter „Übersicht“ enthält sechs Karten, die auf großen Bildschirmen in zwei Spalten angeordnet sind und bei schmalem Fenster untereinander stehen. Jede Karte nennt oben eine oder zwei große Kennzahlen und darunter die Aufschlüsselung als Liste. Der farbige Balken im Hintergrund einer Listenzeile zeigt deren Anteil am größten Wert der Liste.</p><p><img src="'+c+'" alt="Screenshot Dashboard mit Hervorhebung der Karten im Reiter „Übersicht“ in der Inhaltsfläche" data-zoomable="true"></p><h4 id="trassenstatistik" tabindex="-1">Trassenstatistik <a class="header-anchor" href="#trassenstatistik" aria-label="Permalink to &quot;Trassenstatistik&quot;">​</a></h4><ul><li>Kennzahl: die Gesamtlänge aller Trassen, gefolgt von „km Gesamtlänge“.</li><li>Je Listenzeile: die Verlegeart in fetter Schrift, darunter kleiner die Oberfläche.</li><li>Rechts in der Zeile: die Länge dieser Kombination in Kilometern.</li></ul><h4 id="netzknotenstatistik" tabindex="-1">Netzknotenstatistik <a class="header-anchor" href="#netzknotenstatistik" aria-label="Permalink to &quot;Netzknotenstatistik&quot;">​</a></h4><ul><li>Kennzahl: die Anzahl aller Netzknoten mit angehängtem „x“ und der Beschriftung „Gesamtzahl“.</li><li>Je Listenzeile: der Knotentyp und rechts die Anzahl, ebenfalls mit angehängtem „x“.</li></ul><h4 id="rohrstatistiken" tabindex="-1">Rohrstatistiken <a class="header-anchor" href="#rohrstatistiken" aria-label="Permalink to &quot;Rohrstatistiken&quot;">​</a></h4><ul><li>Kennzahl: die Gesamtlänge aller Rohre, gefolgt von „km Leerrohr-Gesamtlänge“.</li><li>Je Listenzeile: der Rohrtyp und rechts dessen Länge in Kilometern.</li></ul><h4 id="adress-statistiken" tabindex="-1">Adress-Statistiken <a class="header-anchor" href="#adress-statistiken" aria-label="Permalink to &quot;Adress-Statistiken&quot;">​</a></h4><ul><li>Zwei Kennzahlen nebeneinander: „Adressen gesamt“ und „Wohneinheiten gesamt“, beide mit angehängtem „x“.</li><li>Je Listenzeile: der Ort und rechts die Anzahl der Adressen. Adressen ohne Ortsangabe erscheinen unter „Unbekannt“.</li></ul><h4 id="gebietsstatistiken" tabindex="-1">Gebietsstatistiken <a class="header-anchor" href="#gebietsstatistiken" aria-label="Permalink to &quot;Gebietsstatistiken&quot;">​</a></h4><ul><li>Zwei Kennzahlen nebeneinander: „Anzahl Gebiete“ mit angehängtem „x“ und die Gesamtfläche in „km²“.</li><li>Je Listenzeile: der Gebietstyp und rechts die Anzahl der Gebiete. Gebiete ohne Typ erscheinen unter „Unbekannt“.</li></ul><h4 id="gewahrleistung" tabindex="-1">Gewährleistung <a class="header-anchor" href="#gewahrleistung" aria-label="Permalink to &quot;Gewährleistung&quot;">​</a></h4><p>Diese Karte zeigt bis zu fünf Netzknoten, deren Gewährleistungsfrist als nächste abläuft, aufsteigend nach Datum sortiert. Je Eintrag stehen links der Name des Netzknotens und darunter, sofern hinterlegt, sein Knotentyp, rechts die verbleibende Restlaufzeit – etwa „14 Tagen“, bei einem einzelnen Tag „1 Tag“ – und darunter das Ablaufdatum im Format TT.MM.JJJJ. Am Tag des Ablaufs steht anstelle der Restlaufzeit „Läuft ab am“ mit dem Datum.</p><p>Die Einträge sind nach Dringlichkeit farbig hinterlegt:</p><ul><li>rot: weniger als 30 Tage Restlaufzeit</li><li>gelb: weniger als 90 Tage Restlaufzeit</li><li>grün: 90 Tage Restlaufzeit oder mehr</li></ul><p>Sind für das Projekt keine Fristen hinterlegt, erscheint stattdessen „Keine Garantien laufen bald ab“.</p><p><img src="'+g+'" alt="Screenshot Dashboard mit Hervorhebung der Karte „Gewährleistung“ und ihren farbig hinterlegten Einträgen unten rechts in der Inhaltsfläche" data-zoomable="true"></p><p>Wichtig: Die Karte ist keine vollständige Liste aller Gewährleistungsfristen des Projekts. Sie zeigt höchstens fünf Netzknoten, und bereits abgelaufene Fristen erscheinen nicht mehr. Die Angaben stammen aus dem Feld „Gewährleistung“ des jeweiligen Netzknotens; die Frist eines einzelnen Netzknotens finden Sie in der Karte in der Info-Box im Reiter „Eigenschaften“ (siehe Kapitel <a href="./05-karte.html">Karte</a>).</p><p>Hinweis: Alle sechs Karten begrenzen die Höhe ihrer Liste. Sind mehr Zeilen vorhanden als angezeigt werden, scrollen Sie innerhalb der Karte nach unten. Nutzen Sie dazu das Scrollrad Ihrer Maus oder ein Touchpad, während der Zeiger über der Liste steht.</p><h3 id="_4-2-2-trasse" tabindex="-1">4.2.2 Trasse <a class="header-anchor" href="#_4-2-2-trasse" aria-label="Permalink to &quot;4.2.2 Trasse&quot;">​</a></h3><p>Im Reiter „Trasse“ finden Sie acht waagerechte Balkendiagramme zu den Trassen des Projekts. Die x-Achse ist jeweils beschriftet, in der Regel mit „Länge (km)“:</p><ul><li>„Gesamtlänge pro Oberfläche“</li><li>„Gesamtlänge pro Verlegeart“</li><li>„Durchschnittliche Hausanschlusslänge“ – ein einzelner Balken, Achse in Metern („Länge (m)“)</li><li>„Länge gefördert“ – ein einzelner Balken über die als gefördert gekennzeichneten Trassen</li><li>„Länge Eigenleistung“ – ein einzelner Balken über die in Eigenleistung erbrachten Trassen</li><li>„Gesamtlänge pro Status“</li><li>„Gesamtlänge pro Netzebene“</li><li>„Längsten Trassen im Netz“ – die fünf längsten Trassen, beschriftet mit Verlegeart und Oberfläche</li></ul><p class="img-row"><img src="'+m+'" alt="Screenshot Dashboard mit Hervorhebung der Diagramme im Reiter „Trasse“ in der Inhaltsfläche" data-zoomable="true"><img src="'+b+'" alt="Screenshot Ausschnittvergrößerung des Diagramms „Gesamtlänge pro Oberfläche“ mit dem Tooltip über einem Balken" data-zoomable="true"></p><p>Genaue Werte lesen Sie einzeln ab: Zeigen Sie mit der Maus auf einen Balken, erscheint ein Tooltip mit dem Wert und seiner Einheit. Die Achsenbeschriftung selbst nennt nur die Skala, nicht die einzelnen Werte.</p>',29),e("p",null,[e("video",{src:p,controls:"",playsinline:"",preload:"metadata"},[n(" Ihr Browser unterstützt das Abspielen von HTML5-Videos nicht. Sie können die Datei "),e("a",{href:"/videos/dashboard_chart_hover.webm",download:""},"herunterladen"),n(" anstelle des Videos. ")])],-1),i('<h3 id="_4-2-3-rohre" tabindex="-1">4.2.3 Rohre <a class="header-anchor" href="#_4-2-3-rohre" aria-label="Permalink to &quot;4.2.3 Rohre&quot;">​</a></h3><p>Der Reiter „Rohre“ wertet die Rohre des Projekts aus. Ganz oben steht der Kasten „Top 5 längste Rohre“ mit bis zu fünf Feldern; jedes Feld nennt seinen Rang („#1“ bis „#5“), den Namen des Rohrs, dessen Typ und die Länge in Kilometern. Sind keine Rohre vorhanden, fehlt dieser Kasten vollständig.</p><p>Darunter folgen die Diagramme in dieser Reihenfolge:</p><ul><li>„Länge nach Rohrtyp“ – waagerechte Balken, Achse in Kilometern</li><li>„Länge nach Status und Typ“ – gestapelte Balken; die Legende über dem Diagramm erklärt, welche Farbe zu welchem Rohrtyp gehört</li><li>„Gesamtlänge pro Netzebene“ – Ringdiagramm mit Legende an der rechten Seite</li><li>„Durchschnittliche Länge nach Typ“ – waagerechte Balken, Achse in Metern</li><li>„Anzahl Rohre nach Status“ – waagerechte Balken, Achse „Anzahl“</li><li>„Länge nach Eigentümer“ – waagerechte Balken, Achse in Kilometern</li><li>„Länge nach Hersteller“ – Ringdiagramm mit Legende an der rechten Seite</li><li>„Rohre im Zeitverlauf“ – Anzahl der Rohre je Monat; die Monate sind im Format „JJJJ-MM“ beschriftet</li></ul><p><img src="'+k+'" alt="Screenshot Dashboard mit Hervorhebung der Auswertungen im Reiter „Rohre“ in der Inhaltsfläche" data-zoomable="true"></p><p>Auch in den Ringdiagrammen erhalten Sie den genauen Wert, indem Sie mit der Maus auf ein Segment zeigen; der Tooltip nennt dort zusätzlich den Anteil in Prozent. Angelegt und bearbeitet werden Rohre im Bereich Rohrverwaltung, siehe Kapitel <a href="./06-rohrverwaltung.html">Rohrverwaltung</a>.</p><h3 id="_4-2-4-netzknoten" tabindex="-1">4.2.4 Netzknoten <a class="header-anchor" href="#_4-2-4-netzknoten" aria-label="Permalink to &quot;4.2.4 Netzknoten&quot;">​</a></h3><p>Der Reiter „Netzknoten“ enthält sechs waagerechte Balkendiagramme; die Achse ist überall die Anzahl:</p><ul><li>„Netzknoten nach Ort“</li><li>„Netzknoten nach Status“</li><li>„Netzknoten nach Netzebene“</li><li>„Netzknoten nach Typ“</li><li>„Netzknoten nach Eigentümer“</li><li>„Neueste Netzknoten“</li></ul><p><img src="'+z+'" alt="Screenshot Dashboard mit Hervorhebung der Diagramme im Reiter „Netzknoten“ in der Inhaltsfläche" data-zoomable="true"></p><p>Hinweis: „Neueste Netzknoten“ ist eine Aufzählung, keine Mengenauswertung. Das Diagramm listet die fünf zuletzt datierten Netzknoten mit Namen und Typ auf; alle Balken sind deshalb gleich lang. Netzknoten ohne Datum bleiben unberücksichtigt. Auch in den übrigen Diagrammen werden Netzknoten übergangen, bei denen die jeweilige Angabe fehlt – die Summe der Balken muss daher nicht der Gesamtzahl aus dem Reiter „Übersicht“ entsprechen.</p><h3 id="_4-2-5-adressen" tabindex="-1">4.2.5 Adressen <a class="header-anchor" href="#_4-2-5-adressen" aria-label="Permalink to &quot;4.2.5 Adressen&quot;">​</a></h3><p>Der Reiter „Adressen“ wertet Adressen und Wohneinheiten aus und enthält vier Diagramme:</p><ul><li>„Adressen nach Ort“ – waagerechte Balken, Achse „Anzahl (x)“</li><li>„Adressen nach Ausbaustatus“ – waagerechte Balken, Achse „Anzahl (x)“</li><li>„Wohneinheiten nach Ort“ – waagerechte Balken, Achse „Anzahl (x)“</li><li>„Wohneinheiten nach Typ“ – Ringdiagramm mit Legende an der rechten Seite</li></ul><p><img src="'+f+'" alt="Screenshot Dashboard mit Hervorhebung der Diagramme im Reiter „Adressen“ in der Inhaltsfläche" data-zoomable="true"></p><h3 id="_4-2-6-gebiete" tabindex="-1">4.2.6 Gebiete <a class="header-anchor" href="#_4-2-6-gebiete" aria-label="Permalink to &quot;4.2.6 Gebiete&quot;">​</a></h3><p>Der Reiter „Gebiete“ zeigt, wie viele Gebiete im Projekt hinterlegt sind und welcher Anteil des Bestands innerhalb dieser Gebiete liegt. Er ist in drei Blöcke gegliedert.</p><p>In der ersten Reihe stehen drei Karten:</p><ul><li>„Anzahl Gebiete“ – die Anzahl der Gebiete als große Zahl</li><li>„Gesamtfläche“ – die Summe der Gebietsflächen in „km²“</li><li>„Gebiete nach Typ“ – Ringdiagramm über die Gebietstypen</li></ul><p>Darunter folgen drei Karten zur <strong>Abdeckung</strong>. Jede nennt den Wert innerhalb der Gebiete und, durch einen Schrägstrich getrennt, den Gesamtwert des Projekts; darunter steht der Anteil in Prozent:</p><ul><li>„Adress-Abdeckung“</li><li>„Netzknoten-Abdeckung“</li><li>„Wohneinheiten-Abdeckung“</li></ul><p>Den unteren Block bilden sechs waagerechte Balkendiagramme:</p><ul><li>„Adressen pro Gebiet“</li><li>„Adressen nach Gebietstyp“</li><li>„Netzknoten pro Gebiet“</li><li>„Netzknoten nach Gebietstyp“</li><li>„Trassenlänge pro Gebiet“ – Achse in Kilometern</li><li>„Wohneinheiten nach Gebietstyp“</li></ul><p><img src="'+w+'" alt="Screenshot Dashboard mit Hervorhebung der Karten und Diagramme im Reiter „Gebiete“ in der Inhaltsfläche" data-zoomable="true"></p><p>Wichtig: Die drei Diagramme „Adressen pro Gebiet“, „Netzknoten pro Gebiet“ und „Trassenlänge pro Gebiet“ zeigen höchstens die zehn Gebiete mit den höchsten Werten. Bei mehr als zehn Gebieten ist die Auswertung also keine vollständige Liste. Der Prozentwert in den drei Karten zur Abdeckung ist auf ganze Zahlen gerundet.</p>',25)])])}const v=a(_,[["render",A]]);export{P as __pageData,v as default};
